                "id", r.id,
                "roomNumber", r.roomNumber,
                "guestName", r.guestName,
                "guestEmail", r.guestEmail,
                "guestCpf", r.guestCpf,
                "checkIn", Dates.formatCsv(r.checkIn),
                "checkOut", Dates.formatCsv(r.checkOut),
                "guests", r.guests,
                "ratePlan", r.ratePlan.name(),
                "nights", r.nights,
                "subtotal", r.subtotal,
                "discount", r.discount,
                "total", r.total,
                "status", r.status.name(),
                "amountPaid", r.amountPaid,
                "refund", r.refund
        );
    }

    private static Map<String, Object> receiptToDto(Reservation r, String receipt) {
        return Map.of(
                "title", "Comprovante de reserva",
                "reservationId", r.id,
                "guestName", r.guestName,
                "guestCpf", r.guestCpf,
                "roomNumber", r.roomNumber,
                "roomType", "", // Will be fetched by service
                "checkIn", Dates.formatCsv(r.checkIn),
                "checkOut", Dates.formatCsv(r.checkOut),
                "nights", r.nights,
                "subtotal", r.subtotal,
                "discount", r.discount,
                "total", r.total
        );
    }

    private static void sendError(Context ctx, String code, String message, int status) {
        ctx.status(status).json(Map.of("error", code, "message", message));
    }
}

